// Recorded acoustic battle sound effects: compact CC0 soundbank embedded as base64.
// Replaces raw synth oscillators with authentic recorded steel slashes, shield clashes,
// blunt impacts, arrow strikes, and explosions.

export type CombatSample = 'hitSword' | 'hitBlunt' | 'block' | 'crit' | 'bow' | 'arrowHit' | 'death' | 'boom';

export const COMBAT_AUDIO_DATA: Record<CombatSample, string> = {
  hitSword: '',
  hitBlunt: '',
  block: '',
  crit: '',
  bow: '',
  arrowHit: '',
  death: '',
  boom: '',
};

function base64ToArrayBuffer(base64: string): ArrayBuffer {
  const binary = atob(base64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes.buffer;
}

/** Pre-decoded audio buffer bank for battle sound effects. */
export class CombatAudioBank {
  private buffers = new Map<CombatSample, AudioBuffer>();
  private decoding = false;

  async load(ctx: BaseAudioContext): Promise<void> {
    if (this.decoding || this.buffers.size > 0 || typeof ctx.decodeAudioData !== 'function') return;
    this.decoding = true;
    for (const [id, b64] of Object.entries(COMBAT_AUDIO_DATA)) {
      try {
        const ab = base64ToArrayBuffer(b64);
        const buf = await new Promise<AudioBuffer>((resolve, reject) => {
          const res = ctx.decodeAudioData(ab, resolve, reject);
          if (res && typeof res.then === 'function') res.then(resolve, reject);
        });
        this.buffers.set(id as CombatSample, buf);
      } catch {
        // Fall back to synthetic voice
      }
    }
  }

  get(id: CombatSample): AudioBuffer | undefined {
    return this.buffers.get(id);
  }
}
